var c=UnityEngine.Object.FindAnyObjectByType<CatGunner.Recovery.RecoveryForestClient>(FindObjectsInactive.Include);var all=c.Slider.GetComponentInParent<Canvas>().GetComponentsInChildren<Transform>(true);return new{slots=c.Guns.Gun_Slot_List.Select(s=>new{star=s.StarUpgrade_obj.name,starPath=s.StarUpgrade_obj.transform.parent.name,lv=s.StarUpgrade_Lv_txt.name,text=s.StarUpgrade_Lv_txt.text,nodes=s.GetComponentsInChildren<Transform>(true).Where(t=>t.name.Contains("Star")||t.name.Contains("Upgrade")).Select(t=>new{t.name,parent=t.parent.name,active=t.gameObject.activeSelf,button=t.GetComponent<UnityEngine.UI.Button>()?.interactable,txt=t.GetComponent<TMPro.TextMeshProUGUI>()?.text})}),menus=all.Where(t=>t.name=="Left_Menu"||t.name=="Right_Menu").Select(t=>new{t.name,children=t.Cast<Transform>().Select(ch=>new{ch.name,active=ch.gameObject.activeSelf,rect=((RectTransform)ch).rect.ToString(),components=ch.GetComponents<Component>().Select(b=>b.GetType().Name)})})};
